def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings representing integers or '+', '-', '*', '/'.
    Division truncates toward zero (as per problem statement).
    Returns int.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/')):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero: use int(a / b)
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

