def solve(s):
    """Return True if brackets in s are balanced, else False.
    Supports parentheses (), square brackets [], and curly braces {}.
    Ignores all other characters. Non-string inputs return False.
    """
    if not isinstance(s, str):
        return False
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings representing integers or operators '+', '-', '*', '/'.
    Division truncates toward zero as specified.
    Returns integer result.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

