def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search (O(n log n)).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find position to replace (first >= x) because subsequence must be strictly increasing
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

