def solve(word1, word2):
    # classic edit distance DP O(mn)
    m, n = len(word1), len(word2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],    # delete
                                   dp[i][j-1],    # insert
                                   dp[i-1][j-1])  # replace
    return dp[m][n]

def solve(s):
    """Run‑length encoding for any iterable.
    Returns a list of [element, count] pairs for consecutive identical elements.
    If *s* is not iterable, returns an empty list.
    """
    try:
        seq = list(s)
    except Exception:
        return []
    if not seq:
        return []
    res = []
    cur = seq[0]
    cnt = 1
    for ch in seq[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

