def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting method with binary search (bisect_left).
    """
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

